package thaumcraft.common.entities;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class Mob8NaturalRulesTest {
    @Test void giantInitialAngerZeroReallyProducesTwoDamage(){assertEquals(2,Mob8NaturalRules.giantAttack(0));assertEquals(7,Mob8NaturalRules.giantAttack(1));assertEquals(12,Mob8NaturalRules.giantAttack(2));assertEquals(2,Mob8NaturalRules.giantAnger(2));assertEquals(.1F,Mob8NaturalRules.giantAnger(0));}
    @Test void sourceTradeTierNeverExceedsFiveAndRetainsCeilingHalf(){for(int value=1;value<=4098;value++)for(int roll:new int[]{0,value/2,value-1})assertEquals(Math.min(5,Math.max((value+1)/2,roll+1)),Mob8NaturalRules.tradeTier(value,roll));assertThrows(IllegalArgumentException.class,()->Mob8NaturalRules.tradeTier(0,0));assertThrows(IllegalArgumentException.class,()->Mob8NaturalRules.tradeTier(3,3));}
    @Test void explicitValuablesOverrideDesireAndDesireCapsAtThirtyTwo(){assertEquals(15,Mob8NaturalRules.pechValue(15,128));assertEquals(0,Mob8NaturalRules.pechValue(0,1));assertEquals(1,Mob8NaturalRules.pechValue(0,3));assertEquals(32,Mob8NaturalRules.pechValue(0,256));}
    @Test void wispStationaryThresholdUsesSourceFloatBoundary(){assertTrue(Mob8NaturalRules.wispStationary(.1F,-.1F,0));assertFalse(Mob8NaturalRules.wispStationary(.10001,0,0));assertFalse(Mob8NaturalRules.wispStationary(0,0,-.2));}
    @Test void pechEquipmentHasTwoWandFiveBowAndThirteenForagerRolls(){int[] counts=new int[3];for(int roll=0;roll<20;roll++)counts[Mob8NaturalRules.pechWeapon(roll)]++;assertArrayEquals(new int[]{13,2,5},counts);assertThrows(IllegalArgumentException.class,()->Mob8NaturalRules.pechWeapon(20));}
    @Test void rewardInsertionChoosesOneSlotWithoutOverflowOrComponentLaundering(){int[] counts={2,0,0,0},limits={64,64,64,64};boolean[] same={true,false,false,false};assertEquals(0,Mob8NaturalRules.rewardSlot(counts,limits,same,1));counts[0]=63;assertEquals(1,Mob8NaturalRules.rewardSlot(counts,limits,same,1));counts[1]=counts[2]=counts[3]=64;assertEquals(-1,Mob8NaturalRules.rewardSlot(counts,limits,same,1));counts[0]=Integer.MAX_VALUE;assertEquals(-1,Mob8NaturalRules.rewardSlot(counts,limits,same,Integer.MAX_VALUE));}
    @Test void pechArrowKeepsGaussianScaleAndFloatLengthInsteadOfModernTriangularSpread(){double[] velocity=Mob8NaturalRules.arrowHeading(3,4,0,1.6F,2,1,-2,3);double spread=.007499999832361937D*2;assertArrayEquals(new double[]{(.6+spread)*1.6F,(.8-2*spread)*1.6F,3*spread*1.6F},velocity,1E-12);assertArrayEquals(new double[]{0,0,0},Mob8NaturalRules.arrowHeading(0,0,0,1,2,1,1,1));}
}
